struct Data {
    value: i32,
    label: String,
}

fn main() {
    let mut data = Data {
        value: 10,
        label: "test".to_string(),
    };

    // Immutable borrow to read the value
    let v = &data.value;
    let l = &data.label;

    // Mutable borrow to modify the value
    let mut dv = &mut data.value;
    *dv += 1;

    // Assert the final value equals the initial value plus one
    assert_eq!(data.value, 11);

    println!("Ownership test passed");
}
